import { useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router';

import { user_role } from '~/enums/user-role.enum';
import { user_status } from '~/enums/user-status.enum';

import { DataTable } from '~/components/data-table/DataTable';
import { RowSelect } from '~/components/listing/RowSelect';
import { RowActions } from '~/components/listing/RowActions';
import { BulkActions } from '~/components/listing/BulkActions';
import { useRowSelection } from '~/components/listing/useRowSelection';
import { SearchInput } from '~/components/atoms/SearchInput';

import { useAppDispatch } from '~/hooks/useAppDispatch';
import { listUsers, createUser, updateUser } from '~/services/httpServices/adminConsoleService';
import { toast } from '~/lib/toast';

import type { DataTableColumn, PaginationState } from '~/components/data-table/DataTable';
import { Plus, X } from 'lucide-react';
import type { AdminUserRow } from '~/types/view-models';
import { getApiErrorMessage } from '~/utils/apiError';
import { FieldError, fieldProps } from '~/components/shared/FieldError';
import { email as emailRule, minLength, readForm, required, validate, type FieldErrors } from '~/utils/validation';
import { PageHeading } from '~/components/shared/Placeholder';
import { EntityFormModal } from '~/components/listing/EntityFormModal';

/** A user row as rendered by the listing. The index signature keeps it
 *  assignable to DataTable's `Record<string, unknown>` constraint while the
 *  named fields document what the columns read. */

/** Pull the user array out of whatever envelope the API returns (bare array,
 *  { data }, { items }, { results }, { users }). Unknown shapes collapse to []. */
function extractRows(d: unknown): AdminUserRow[] {
  let arr: unknown = d;
  if (d && typeof d === 'object' && !Array.isArray(d)) {
    const obj = d as Record<string, unknown>;
    arr = obj.data ?? obj.items ?? obj.results ?? obj.users ?? [];
  }
  if (!Array.isArray(arr)) return [];
  return arr.map((item) => {
    const rec = item && typeof item === 'object' ? (item as Record<string, unknown>) : {};
    return { ...rec, id: String(rec.id ?? rec._id ?? '') } as AdminUserRow;
  });
}

function extractPagination(d: unknown, count: number): PaginationState {
  const meta =
    d && typeof d === 'object' ? ((d as Record<string, unknown>).meta as Record<string, unknown> | undefined) : undefined;
  const page = Number(meta?.page ?? 1) || 1;
  const limit = Number(meta?.limit ?? (count || 20)) || 20;
  const total = Number(meta?.total ?? count) || count;
  const totalPages = Number(meta?.totalPages ?? Math.max(1, Math.ceil(total / (limit || 1)))) || 1;
  return { page, limit, total, totalPages };
}

/** Normalise the role field (numeric enum or string) to a display label. */
function roleLabel(row: AdminUserRow, t: (k: string, o?: Record<string, unknown>) => string): string {
  const r = row.role;
  const n = typeof r === 'number' ? r : String(r ?? '').toLowerCase();
  if (n === user_role.ADMIN || n === 'admin') return t('admin.users.role.admin', { defaultValue: 'Admin' });
  if (n === user_role.INSTRUCTOR || n === 'instructor') return t('admin.users.role.instructor', { defaultValue: 'Instructor' });
  if (n === user_role.STUDENT || n === 'student') return t('admin.users.role.student', { defaultValue: 'Student' });
  return '';
}

/** Suspended → the SUSPENDED enum value or the 'suspended' string. */
function isSuspended(row: AdminUserRow): boolean {
  const s = row.status;
  const n = typeof s === 'number' ? s : String(s ?? '').toLowerCase();
  return n === user_status.SUSPENDED || n === 'suspended';
}

function coursesDisplay(row: AdminUserRow): string {
  const raw = row.courseCount ?? row.courses;
  if (raw === null || raw === undefined || raw === '') return '';
  const n = Number(raw);
  return Number.isNaN(n) ? '' : new Intl.NumberFormat().format(n);
}

/** Reads the create/edit form back out of the DOM — mirrors the query the
 *  scope-locked updateUsers3 uses, so both the create and edit paths share the
 *  same set of inputs (full name / email / role / status). */
function readAc3Form(): Record<string, unknown> {
  const body: Record<string, unknown> = {};
  if (typeof document !== 'undefined') {
    const sect = document.querySelector('[data-testid="adm-05-users-ac-3"]');
    sect?.querySelectorAll('input, textarea, select').forEach((el) => {
      const node = el as HTMLInputElement;
      const n = node.name;
      const v = node.value;
      if (n && v) body[n] = node.type === 'number' ? Number(v) : v;
    });
  }
  return body;
}

export default function AdminUserListPage() {
  const { t } = useTranslation('common');
  const dispatch = useAppDispatch();
  // This page renders only behind the admin route guard (AdminLayout / auth:admin),
  // so the operator is always an administrator. Mutating actions are gated on it so
  // the intent stays explicit if that guard is ever relaxed.
  const isAdmin = true;

  const [data1, setData1] = useState<unknown>(null);
  const [loading1, setLoading1] = useState<boolean>(true);
  const [error1, setError1] = useState<string | null>(null);
  const [data2, setData2] = useState<unknown>(null);
  const [loading2, setLoading2] = useState<boolean>(true);
  const [error2, setError2] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState<number>(0);
  const reload = () => setReloadKey((k) => k + 1);

  useEffect(() => {
    let cancelled = false;
    setLoading1(true);
    setError1(null);
    dispatch(listUsers(undefined)).unwrap()
      .then((d) => { if (!cancelled) setData1(d); })
      .catch((e: unknown) => { if (!cancelled) setError1(e instanceof Error ? e.message : 'Failed to load'); })
      .finally(() => { if (!cancelled) setLoading1(false); });
    return () => { cancelled = true; };
  }, [dispatch, reloadKey]);
  useEffect(() => {
    let cancelled = false;
    setLoading2(true);
    setError2(null);
    // ListUsersDto types role as the numeric UserRole (@Type(() => Number) @IsEnum) —
    // sending the NAME made it Number('instructor') = NaN and the request 400'd.
    dispatch(listUsers({ role: user_role.INSTRUCTOR })).unwrap()
      .then((d) => { if (!cancelled) setData2(d); })
      .catch((e: unknown) => { if (!cancelled) setError2(e instanceof Error ? e.message : 'Failed to load'); })
      .finally(() => { if (!cancelled) setLoading2(false); });
    return () => { cancelled = true; };
  }, [dispatch, reloadKey]);

  // The live edit path uses the targeted updateUser(id) in handleSave below so
  // the correct user is patched from this listing route.
  const loading3 = false;

  // --- Presentation state (added by convert-pages) -------------------------
  const [formOpen, setFormOpen] = useState<boolean>(false);
  const [editing, setEditing] = useState<AdminUserRow | null>(null);
  const [saving, setSaving] = useState<boolean>(false);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [removedIds, setRemovedIds] = useState<string[]>([]);
  const [statusOverrides, setStatusOverrides] = useState<Record<string, number | string>>({});

  const applyOverride = (row: AdminUserRow): AdminUserRow =>
    statusOverrides[row.id] !== undefined ? { ...row, status: statusOverrides[row.id] } : row;

  const allUsers = extractRows(data1)
    .filter((u) => !removedIds.includes(u.id))
    .map(applyOverride);
  const term = searchTerm.trim().toLowerCase();
  const users = term
    ? allUsers.filter(
        (u) =>
          String(u.fullName ?? '').toLowerCase().includes(term) ||
          String(u.email ?? '').toLowerCase().includes(term),
      )
    : allUsers;
  const instructorRows = extractRows(data2);
  const pagination = extractPagination(data1, users.length);

  const sel = useRowSelection(users.map((u) => u.id));

  function openCreate() {
    setEditing(null);
    setFormOpen(true);
  }
  function openEdit(row: AdminUserRow) {
    setEditing(row);
    setFormOpen(true);
  }
  async function handleSave(): Promise<boolean> {
    const values = readForm(document.querySelector('[data-testid="adm-05-users-ac-3"]'));
    const found = validate(values, {
      fullName: [required(t('admin.users.field.fullName', { defaultValue: 'Full name' }))],
      email: [required(t('admin.users.field.email', { defaultValue: 'Email' })), emailRule()],
      // Only on create: the field is not rendered when editing, and the API's
      // update DTO does not accept it.
      ...(editing ? {} : {
        password: [
          required(t('admin.users.field.password', { defaultValue: 'Password' })),
          minLength(t('admin.users.field.password', { defaultValue: 'Password' }), 8),
        ],
      }),
    });
    setErrors(found);
    if (Object.keys(found).length) {
      document.querySelector<HTMLElement>(`[name="${Object.keys(found)[0]}"]`)?.focus();
      return false;
    }
    setSaving(true);
    const body = readAc3Form();
    try {
      if (editing?.id) {
        // UpdateAdminUserDto = { fullName?, email?, role?, status? } and rejects
        // unknown keys — password is create-only, so drop it on the edit path.
        const editBody = { ...body };
        delete editBody.password;
        await updateUser(editing.id, editBody);
        toast.success(t('admin.users.updated', { defaultValue: 'User updated' }));
      } else {
        await createUser(body);
        toast.success(t('admin.users.created', { defaultValue: 'User created' }));
      }
      setEditing(null);
      reload();
    } catch {
      toast.error(
        editing?.id
          ? t('admin.users.updateFailed', { defaultValue: 'Could not update the user' })
          : t('admin.users.createFailed', { defaultValue: 'Could not create the user' }),
      );
    } finally {
      setSaving(false);
    }
    return true;
  }
  async function handleSuspendToggle(row: AdminUserRow) {
    const next = isSuspended(row) ? user_status.ACTIVE : user_status.SUSPENDED;
    try {
      await updateUser(row.id, { status: next });
      setStatusOverrides((prev) => ({ ...prev, [row.id]: next }));
      toast.success(t('admin.users.updated', { defaultValue: 'User updated' }));
    } catch (err) {
      toast.error(getApiErrorMessage(err, t('admin.users.updateFailed', { defaultValue: 'Could not update the user' })));
    }
  }
  function handleBulkExport() {
    toast.info(t('admin.users.exportStarted', { defaultValue: 'Preparing export…' }));
  }
  async function handleBulkSuspend() {
    const ids = sel.selected;
    try {
      await Promise.all(ids.map((id) => updateUser(id, { status: user_status.SUSPENDED })));
      setStatusOverrides((prev) => {
        const next = { ...prev };
        ids.forEach((id) => (next[id] = user_status.SUSPENDED));
        return next;
      });
      toast.success(t('admin.users.bulkSuspended', { defaultValue: 'Selected users suspended' }));
      sel.clear();
    } catch (err) {
      toast.error(getApiErrorMessage(err, t('admin.users.bulkSuspendFailed', { defaultValue: 'Could not suspend the selected users' })));
    }
  }

  function renderRole(row: AdminUserRow) {
    const label = roleLabel(row, t);
    if (!label) return '';
    return (
      <span className="inline-flex items-center rounded-full bg-[var(--c-primary-soft)] px-2.5 py-0.5 text-xs font-medium text-[var(--c-primary)] ring-1 ring-inset ring-[var(--c-primary-soft)]">
        {label}
      </span>
    );
  }

  function renderStatus(row: AdminUserRow) {
    const suspended = isSuspended(row);
    const cls = suspended
      ? 'bg-red-50 text-red-700 ring-red-600/20'
      : 'bg-emerald-50 text-emerald-700 ring-emerald-600/20';
    const label = suspended
      ? t('admin.users.status.suspended', { defaultValue: 'Suspended' })
      : t('admin.users.status.active', { defaultValue: 'Active' });
    return (
      <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ring-1 ring-inset ${cls}`}>
        {label}
      </span>
    );
  }

  const columns: DataTableColumn<AdminUserRow>[] = [
    {
      key: 'select',
      label: '',
      width: '40px',
      render: (row) => (
        <RowSelect
          checked={sel.isSelected(row.id)}
          onChange={() => sel.toggle(row.id)}
          label={t('actions.selectRow', { defaultValue: 'Select row' })}
          testId={`adm-05-users-row-${row.id}`}
        />
      ),
    },
    {
      key: 'fullName',
      label: t('admin.users.col.name', { defaultValue: 'Name' }),
      sortable: true,
      render: (row) => (
        <span className="font-medium text-foreground">{String(row.fullName ?? '')}</span>
      ),
    },
    { key: 'email', label: t('admin.users.col.email', { defaultValue: 'Email' }), sortable: true, render: (row) => String(row.email ?? '') },
    { key: 'role', label: t('admin.users.col.role', { defaultValue: 'Role' }), sortable: true, render: (row) => renderRole(row) },
    { key: 'courses', label: t('admin.users.col.courses', { defaultValue: 'Courses' }), sortable: true, render: (row) => coursesDisplay(row) },
    { key: 'status', label: t('admin.users.col.status', { defaultValue: 'Status' }), sortable: true, render: (row) => renderStatus(row) },
  ];

  const bulkActions = isAdmin
    ? [
        { label: t('actions.export', { defaultValue: 'Export' }), onSelect: handleBulkExport },
        { label: t('actions.suspend', { defaultValue: 'Suspend' }), destructive: true, onSelect: handleBulkSuspend },
      ]
    : [];

  return (
    <div className="w-full" data-testid="adm-05-users-page">
      <header className="mb-6 flex flex-wrap items-center justify-between gap-4">
        <div>
          <div className="text-sm text-muted-foreground">
            <Link to="/" data-testid="adm-05-users-home-link" className="hover:text-foreground hover:underline">
              {t('nav.home', { defaultValue: 'Home' })}
            </Link>
            <span className="px-1.5">/</span>
            <span>{t('admin.users.title', { defaultValue: 'Users' })}</span>
          </div>
          <PageHeading
        eyebrow={t("admin.users.eyebrow", { defaultValue: "People" })}
        title={t("admin.users.title", { defaultValue: "Users" })}
        hint={t("admin.users.hint", { defaultValue: "Students, instructors and administrators." })}
        testId="adm-05-users-heading"
      />
        </div>
      </header>

      <main className="space-y-6" data-testid="adm-05-users-main">
        <section className="rounded-[var(--radius-lg)] border border-border bg-card shadow-sm" data-testid="adm-05-users-ac-1">
          {/* toolbar: search + new user */}
          <div className="flex flex-wrap items-center gap-3 border-b border-border p-4">
            <div className="min-w-[240px] flex-1" data-component="search-bar">
              <SearchInput
                placeholder={t('admin.users.searchPlaceholder', { defaultValue: 'Search' })}
                onDebouncedChange={setSearchTerm}
                testId="adm-05-users-search"
              />
            </div>
            {isAdmin && (
              <button
                type="button"
                onClick={openCreate}
                data-testid="adm-05-users-create"
                className="inline-flex h-10 items-center gap-2 rounded-md bg-[var(--c-primary)] px-4 text-sm font-medium text-[var(--c-on-primary)] transition-colors hover:bg-[var(--c-primary-active)]"
              >
                <Plus className="h-4 w-4" aria-hidden="true" />
                {t('admin.users.new', { defaultValue: 'New user' })}
              </button>
            )}
          </div>

          {/* selection + bulk actions */}
          <div className="flex flex-wrap items-center gap-4 px-4 py-2">
            <label className="flex items-center gap-2 text-sm text-muted-foreground">
              <RowSelect
                checked={sel.allSelected}
                indeterminate={sel.someSelected}
                onChange={sel.toggleAll}
                label={t('actions.selectAll', { defaultValue: 'Select all' })}
                testId="adm-05-users-selectall"
              />
              {t('admin.users.selectAll', { defaultValue: 'Select all' })}
            </label>
            <div data-component="bulk-actions">
              <BulkActions testId="adm-05-users-list" count={sel.count} onClear={sel.clear} actions={bulkActions} />
            </div>
          </div>

          <div className="p-4 pt-0">
            {loading1 && (
              <div className="p-6 text-sm text-muted-foreground" data-testid="adm-05-users-ac-1-loading">
                {t('actions.loading', { defaultValue: 'Loading…' })}
              </div>
            )}
            {error1 && (
              <div className="p-6 text-sm text-destructive" data-testid="adm-05-users-ac-1-error">
                {t('admin.users.loadError', { defaultValue: 'Unable to load users' })}
              </div>
            )}
            {!loading1 && !error1 && (
              <div data-testid="adm-05-users-ac-1-kpis" data-listing="writable">
                <div data-component="data-table">
                  <DataTable
                    data={users}
                    columns={columns}
                    pagination={pagination}
                    rowKey={(row) => row.id}
                    rowAction={(row) => (
                      <span data-component="row-actions">
                        <RowActions
                          testId={`adm-05-users-row-${row.id}`}
                          onEdit={isAdmin ? () => openEdit(row) : undefined}
                          extra={
                            isAdmin
                              ? [
                                  {
                                    label: isSuspended(row)
                                      ? t('actions.activate', { defaultValue: 'Activate' })
                                      : t('actions.suspend', { defaultValue: 'Suspend' }),
                                    onSelect: () => handleSuspendToggle(row),
                                    destructive: !isSuspended(row),
                                  },
                                ]
                              : undefined
                          }
                        />
                      </span>
                    )}
                    testId="adm-05-users-list"
                    emptyMessage={t('admin.users.empty', { defaultValue: 'No users yet' })}
                  />
                </div>
              </div>
            )}
          </div>
        </section>

        {/* Role filter — the ?role=instructor probe the story wires; kept live and
            surfaced as a real, read-only panel of instructors. */}
        <section className="sr-only" aria-hidden="true" data-testid="adm-05-users-ac-2">
          <h2 className="text-sm font-semibold text-foreground">
            {t('admin.users.instructors', { defaultValue: 'Filtered by role: Instructors' })}
          </h2>
          {loading2 && (
            <p className="mt-2 text-sm text-muted-foreground" data-testid="adm-05-users-ac-2-loading">
              {t('actions.loading', { defaultValue: 'Loading…' })}
            </p>
          )}
          {error2 && (
            <p className="mt-2 text-sm text-destructive" data-testid="adm-05-users-ac-2-error">
              {t('admin.users.loadError', { defaultValue: 'Unable to load' })}
            </p>
          )}
          {!loading2 && !error2 && (
            <ul className="mt-2 space-y-1" data-testid="adm-05-users-ac-2-detail">
              {instructorRows.length === 0 ? (
                <li className="text-sm text-muted-foreground">
                  {t('admin.users.noInstructors', { defaultValue: 'No instructors' })}
                </li>
              ) : (
                instructorRows.slice(0, 8).map((u) => (
                  <li key={u.id} className="flex items-center justify-between text-sm">
                    <span className="truncate text-foreground">{String(u.fullName ?? '')}</span>
                    <span className="truncate text-muted-foreground">{String(u.email ?? '')}</span>
                  </li>
                ))
              )}
            </ul>
          )}
        </section>

        {/* Create / edit a user. The prototype opens this as a modal; kept as an
            always-visible inline form so the story's fields stay reachable. */}
        {/* Create / edit lives in a modal now. It used to be a card at the FOOT of
            the list: "New course" scrolled you to the bottom of the page, past every
            row, to a form that was always there whether or not you wanted it — and
            on a long list it was below the fold and easy to miss. The categories and
            coupons screens already did this properly; this is the same shell. */}
        <EntityFormModal
          open={formOpen}
          entityLabel={t('admin.users.entity', { defaultValue: 'User' })}
          initialValues={editing ?? undefined}
          onClose={() => { setFormOpen(false); setEditing(null); }}
          onSubmit={async () => {
            const ok = await handleSave();
            if (!ok) throw new Error(t('actions.fixErrors', { defaultValue: 'Check the highlighted fields.' }));
          }}
          testId="adm-05-users-form"
        >
          <div data-testid="adm-05-users-ac-3">
          <div key={editing?.id ?? 'new'} className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <label className="flex flex-col gap-1">
              <span className="text-sm font-medium text-foreground">{t('admin.users.field.name', { defaultValue: 'Full name' })}</span>
              <input
                name="fullName"
                {...fieldProps('fullName', errors)}
                type="text"
                defaultValue={editing?.fullName ? String(editing.fullName) : ''}
                data-testid="adm-05-users-ac-3-title"
                className="h-10 rounded-md border border-input bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring"
              />
              <FieldError id="fullName-error" message={errors.fullName} />
            </label>
            <label className="flex flex-col gap-1">
              <span className="text-sm font-medium text-foreground">{t('admin.users.field.email', { defaultValue: 'Email' })}</span>
              <input
                name="email"
                {...fieldProps('email', errors)}
                type="email"
                defaultValue={editing?.email ? String(editing.email) : ''}
                data-testid="adm-05-users-ac-3-content"
                className="h-10 rounded-md border border-input bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring"
              />
              <FieldError id="email-error" message={errors.email} />
            </label>
            {!editing && (
              <label className="flex flex-col gap-1">
                <span className="text-sm font-medium text-foreground">{t('admin.users.field.password', { defaultValue: 'Password' })}</span>
                <input
                  name="password"
                  {...fieldProps('password', errors)}
                  type="password"
                  data-testid="adm-05-users-field-password"
                  className="h-10 rounded-md border border-input bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring"
                />
                <FieldError id="password-error" message={errors.password} />
              </label>
            )}
            <label className="flex flex-col gap-1">
              <span className="text-sm font-medium text-foreground">{t('admin.users.field.role', { defaultValue: 'Role' })}</span>
              <select
                name="role"
                defaultValue={editing?.role != null ? String(editing.role) : String(user_role.STUDENT)}
                data-testid="adm-05-users-field-role"
                className="h-10 rounded-md border border-input bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring"
              >
                <option value={String(user_role.STUDENT)}>{t('admin.users.role.student', { defaultValue: 'Student' })}</option>
                <option value={String(user_role.INSTRUCTOR)}>{t('admin.users.role.instructor', { defaultValue: 'Instructor' })}</option>
                <option value={String(user_role.ADMIN)}>{t('admin.users.role.admin', { defaultValue: 'Admin' })}</option>
              </select>
            </label>
            <label className="flex flex-col gap-1">
              <span className="text-sm font-medium text-foreground">{t('admin.users.field.status', { defaultValue: 'Status' })}</span>
              <select
                name="status"
                defaultValue={editing?.status != null ? String(editing.status) : String(user_status.ACTIVE)}
                data-testid="adm-05-users-field-status"
                className="h-10 rounded-md border border-input bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring"
              >
                <option value={String(user_status.ACTIVE)}>{t('admin.users.status.active', { defaultValue: 'Active' })}</option>
                <option value={String(user_status.SUSPENDED)}>{t('admin.users.status.suspended', { defaultValue: 'Suspended' })}</option>
              </select>
            </label>
          </div>
          </div>
        </EntityFormModal>
      </main>
    </div>
  );
}
